def line_amount(quantity, unit_price_cents, tax_rate):
    """Amount in dollars for one line, rounded half-up to the cent."""
    amt = Decimal(quantity) * Decimal(unit_price_cents) * (1 + Decimal(tax_rate)) / 100
    return round(amt, 2)


def monthly_total(month):
